let navSequence=0;
async function navigateTo(input,{history=true,scroll=true}={}){
 const target=new URL(input,location.href);
 if(target.origin!==location.origin||!target.pathname.startsWith(new URL(SITE_BASE,location.origin).pathname)){location.assign(target.href);return}
 const token=++navSequence;
 try{
  const response=await fetch(target.href,{headers:{"X-Requested-With":"CrowRules-PJAX"}});
  if(!response.ok)throw Error("Page request failed ("+response.status+").");
  const markup=await response.text(),parsed=new DOMParser().parseFromString(markup,"text/html"),nextApp=parsed.querySelector("#app"),currentApp=$("#app");
  if(!nextApp||!currentApp)throw Error("The destination page is missing its content area.");
  if(token!==navSequence)return;
  currentApp.innerHTML=nextApp.innerHTML;
  page=parsed.body.dataset.page||"home";
  document.title=parsed.title||"CrowRules Podcasting";
  const description=parsed.querySelector('meta[name="description"]')?.content;
  if(description){let meta=document.querySelector('meta[name="description"]');if(!meta){meta=document.createElement("meta");meta.name="description";document.head.appendChild(meta)}meta.content=description}
  if(history)window.history.pushState({crowrules:true},"",target.href);
  await renderCurrentPage();
  if(scroll)window.scrollTo({top:0,behavior:"instant"});
 }catch(error){console.error("Seamless navigation failed:",error);location.assign(target.href)}
}
function enableSeamlessNavigation(){
 document.addEventListener("click",event=>{
  if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;
  const link=event.target.closest("a[href]");
  if(!link||(link.target&&link.target!=="_self")||link.hasAttribute("download"))return;
  const raw=link.getAttribute("href");if(!raw||raw.startsWith("#")||raw.startsWith("mailto:")||raw.startsWith("tel:")||raw.startsWith("javascript:"))return;
  const target=new URL(link.href,location.href);
  if(target.origin!==location.origin||!target.pathname.startsWith(new URL(SITE_BASE,location.origin).pathname))return;
  if(target.pathname===location.pathname&&target.search===location.search&&target.hash===location.hash)return;
  event.preventDefault();navigateTo(target.href);
 });
 window.addEventListener("popstate",()=>navigateTo(location.href,{history:false}));
}
