 for(const entry of latest.values())counts[entry.role]++;
 const c=$("#liveCreatorCount"),l=$("#liveListenerCount"),g=$("#liveGuestCount");
 if(c)c.textContent=counts.creator;if(l)l.textContent=counts.listener;if(g)g.textContent=counts.guest;
 const ac=$("#adminLiveCreatorCount"),al=$("#adminLiveListenerCount"),ag=$("#adminLiveGuestCount"),at=$("#adminLiveTotal");
