    work.innerHTML='<div class="admin-module admin-awards-module"><div class="admin-module-head"><div><span class="admin-kicker">AWARDS OPERATIONS</span><h3>Voting & nominee management</h3><p>Control voting windows, review community nominations, publish official nominees and prepare each category for voting.</p></div><div class="admin-awards-head-actions"><button class="btn secondary" id="adminAwardsRefresh">↻ Refresh</button><a href="awards.html" class="btn secondary">Public awards ↗</a></div></div>'+
    ((seasons||[]).map(s=>{
      const ns=nominees.filter(n=>n.season_id===s.id),pending=nominations.filter(n=>n.season_id===s.id&&n.status!=="approved"&&n.status!=="rejected");
      return '<section class="admin-award-season" data-award-season="'+s.id+'"><div class="admin-award-season-head"><div><span class="admin-kicker">AWARD SEASON</span><h3>'+esc(s.title)+'</h3><p>'+ns.length+' official nominees · '+pending.length+' nominations awaiting review</p></div><div class="admin-award-statuses"><span>'+badge(s.nominations_open?"Nominations open":"Nominations closed")+'</span><span>'+badge(s.voting_open?"Voting open":"Voting closed")+'</span><span>'+badge(s.results_public?"Results public":"Results hidden")+'</span></div></div><div class="admin-award-controls"><button class="btn '+(s.voting_open?"secondary":"")+'" data-award-action="voting" data-award-id="'+s.id+'" data-value="'+(!s.voting_open)+'">'+(s.voting_open?"Close voting":"Open voting")+'</button><button class="btn secondary" data-award-action="nominations" data-award-id="'+s.id+'" data-value="'+(!s.nominations_open)+'">'+(s.nominations_open?"Close nominations":"Open nominations")+'</button><button class="btn secondary" data-award-action="results" data-award-id="'+s.id+'" data-value="'+(!s.results_public)+'">'+(s.results_public?"Hide results":"Publish results")+'</button></div><div class="admin-award-add-grid"><form class="admin-award-add-form" data-award-add-form="'+s.id+'"><h4>Add an official nominee</h4><label>Category<select name="category" required><option value="">Choose category</option>'+[...new Set(["Host of the Year","Show of the Year","Breakout Creator of the Year","Best Interview","Best Storytelling","Best Community Podcast","Best Sports Podcast","Best News & Culture Podcast","Best Entertainment Podcast","Best Educational Podcast","Best Audio Production","Best Video Podcast","Best Live Podcast","Best Co-Host Duo","Listener’s Choice","Guest of the Year","Rising Voice Award","Community Impact Award","Lifetime Achievement Award",...nominations.filter(x=>x.season_id===s.id).map(x=>x.category)])].map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join("")+'<option value="__custom">+ Custom category</option></select></label><input name="custom_category" class="hidden" placeholder="Enter custom category" maxlength="100"><label>Nominee name<input name="nominee" required maxlength="160" placeholder="Creator, host or show"></label><label>Public link (optional)<input name="public_url" type="url" maxlength="500" placeholder="https://"></label><label>Short description<textarea name="description" maxlength="1200" rows="2" placeholder="Why this nominee deserves recognition"></textarea></label><button class="btn" type="submit">Add nominee to voting</button></form><div class="admin-award-roster"><h4>Official nominee roster <span class="muted">('+ns.length+')</span></h4>'+(ns.length?'<div class="admin-award-roster-list">'+ns.map(n=>'<div class="admin-award-roster-item"><div><b>'+esc(n.nominee)+'</b><small>'+esc(n.category)+' · '+(n.published?"Published":"Unpublished")+'</small></div><button class="btn secondary" data-award-publish="'+n.id+'" data-value="'+(!n.published)+'">'+(n.published?"Unpublish":"Publish")+'</button></div>').join("")+'</div>':empty)+'</div></div><div class="admin-award-nominations"><h4>Community nominations</h4>'+(nominations.filter(n=>n.season_id===s.id).length?'<div class="table-wrap admin-table-wrap"><table><thead><tr><th>Nominee</th><th>Category</th><th>Submitted by</th><th>Status</th><th>Review</th></tr></thead><tbody>'+nominations.filter(n=>n.season_id===s.id).map(n=>'<tr><td><b>'+esc(n.nominee)+'</b><small class="admin-award-reason">'+esc(n.reason||"")+'</small></td><td>'+esc(n.category)+'</td><td>'+esc(n.submitter_name||"Community member")+'</td><td>'+badge(n.status)+'</td><td>'+(n.status==="approved"||n.status==="rejected"?"—":'<button class="btn" data-award-approve="'+n.id+'">Add to voting</button> <button class="btn secondary" data-award-reject="'+n.id+'">Reject</button>')+'</td></tr>').join("")+'</tbody></table></div>':empty)+'</div></section>';
    }).join(""))+
    ((seasons||[]).length?"":empty)+'</div>';
    $("#adminAwardsRefresh").onclick=()=>loadAwards().catch(fail);
